var getTierGroupForLevel = (lvl) => {
	if (lvl <= 0) return LEVEL_TIER_GROUPS[0];
	if (lvl <= 9) return LEVEL_TIER_GROUPS[1];
	if (lvl <= 19) return LEVEL_TIER_GROUPS[2];
	if (lvl <= 29) return LEVEL_TIER_GROUPS[3];
	if (lvl <= 39) return LEVEL_TIER_GROUPS[4];
	if (lvl <= 49) return LEVEL_TIER_GROUPS[5];
	if (lvl <= 59) return LEVEL_TIER_GROUPS[6];
	if (lvl <= 69) return LEVEL_TIER_GROUPS[7];
	if (lvl <= 79) return LEVEL_TIER_GROUPS[8];
	if (lvl <= 89) return LEVEL_TIER_GROUPS[9];
	if (lvl <= 99) return LEVEL_TIER_GROUPS[10];
	return LEVEL_TIER_GROUPS[11];
};
var getUnlockedVip = (lvl) => {
	if (lvl > 0 && lvl % 8 === 0 && lvl <= 96) return lvl / 8;
};
