var ALL_LEVELS_0_TO_100 = RAW_LEVEL_0_TO_100.map(([level, totalCumulativeCoins, additionalCoins]) => {
	const tierGroup = getTierGroupForLevel(level);
	return {
		level,
		totalCumulativeCoins,
		additionalCoins,
		tier: tierGroup.name,
		tierGroup: tierGroup.tierGroup,
		tierName: tierGroup.name,
		tierBadge: tierGroup.badge,
		tierColor: tierGroup.color,
		gradientBg: tierGroup.gradientBg,
		borderColor: tierGroup.borderColor,
		unlockedVipTier: getUnlockedVip(level)
	};
});
var ALL_LEVELS_1_TO_100 = ALL_LEVELS_0_TO_100;
var formatCoinsCompact = (coins) => {
	if (coins >= 1e9) return `${(coins / 1e9).toFixed(coins % 1e9 === 0 ? 0 : 2)}B`;
	if (coins >= 1e6) return `${(coins / 1e6).toFixed(coins % 1e6 === 0 ? 0 : 1)}M`;
	if (coins >= 1e3) return `${(coins / 1e3).toFixed(0)}K`;
	return coins.toLocaleString();
};
var getLevelConfig = (lvl) => {
	return ALL_LEVELS_0_TO_100[Math.max(0, Math.min(100, Math.floor(lvl || 0)))];
};
var getNextLevelConfig = (currentLvl) => {
	if (currentLvl >= 100) return null;
	return ALL_LEVELS_0_TO_100[Math.max(0, currentLvl) + 1];
};
var getNextVipUnlockInfo = (currentLevel, totalCoins = 0) => {
	const currentVipTier = Math.min(12, Math.floor(currentLevel / 8));
	const nextVipTier = currentVipTier < 12 ? currentVipTier + 1 : 12;
	const targetLevel = nextVipTier * 8;
	if (targetLevel > 96 || currentVipTier >= 12) return {
		currentVipTier: 12,
		nextVipTier: 12,
		targetLevel: 96,
		requiredCoins: ALL_LEVELS_0_TO_100[96].totalCumulativeCoins,
		levelsRemaining: 0,
		coinsRemaining: 0,
		isMaxVip: true
	};
	const requiredCoins = ALL_LEVELS_0_TO_100[targetLevel].totalCumulativeCoins;
	const currentLevelConfig = ALL_LEVELS_0_TO_100[Math.max(0, currentLevel)];
	const estimatedUserCoins = Math.max(totalCoins, currentLevelConfig.totalCumulativeCoins);
	const coinsRemaining = Math.max(0, requiredCoins - estimatedUserCoins);
	return {
		currentVipTier,
		nextVipTier,
		targetLevel,
		requiredCoins,
		levelsRemaining: Math.max(0, targetLevel - currentLevel),
		coinsRemaining,
		isMaxVip: false
	};
};
